from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_is_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"a": [event("a", 1, True)], "b": [event(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (3, 9), (10, 9)])
def test_flags_in_window(days, expected):
    assert flags_in_window([2, 3, 4], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_fields_whitespace_flags_and_skipped_lines():
    assert parse_transcript_log(["  # comment,with,commas\n", "\n", "  \t", " x , -2 , 1 ", "y,3,0", " z, 4, "]) == [
        event("x", -2, True), event("y", 3, False), event("z", 4, None)
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,not-an-int,1", "x,1,yes"])
def test_parse_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", "  ", "valid,1,0", bad_line])


def test_dedupe_keeps_last_duplicate_id_then_sorts_by_day_and_id():
    events = [event("x", 1, True), event("z", 2, True), event("a", 2, False), event("x", 3, None), event("x", 2, False)]
    assert dedupe_transcripts(events) == [event("a", 2, False), event("x", 2, False), event("z", 2, True)]


def test_daily_flag_counts_fills_gaps_and_restricts_range():
    events = [event("a", 1, True), event("b", 2, None), event("c", 3, True), event("d", 3, True), event("e", 5, True)]
    assert daily_flag_counts(events, 2, 4) == [0, 2, 0]
    assert daily_flag_counts([], 2, 4) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_pooled_rate_days_and_nonempty_groups():
    groups = {
        "a": [event("a", 1, True)],
        "b": [event("b", 3, False), event("c", 3, None), event("d", 3, False), event("e", 3, False), event("f", 3, False)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [], "b": [event("b", 1, False)], "a": [event("a", 1, True)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_includes_empty_and_sorts_keys():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_on_zero_and_negative_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
